import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        int N = sc.nextInt();

        int[] p = new int[N + 1];
        ArrayList<Integer>[] children = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) children[i] = new ArrayList<>();

        for (int i = 2; i <= N; i++) {
            p[i] = sc.nextInt();
            children[p[i]].add(i);
        }

        int[] tin = new int[N + 1];
        int[] tout = new int[N + 1];
        int[] iter = new int[N + 1];
        int[] stack = new int[N + 1];

        int top = 0;
        int timer = 0;
        stack[top++] = 1;
        tin[1] = ++timer;

        while (top > 0) {
            int v = stack[top - 1];
            if (iter[v] < children[v].size()) {
                int c = children[v].get(iter[v]++);
                tin[c] = ++timer;
                stack[top++] = c;
            } else {
                tout[v] = timer;
                top--;
            }
        }

        int LOG = 1;
        while ((1 << LOG) <= N) LOG++;

        int[][] up = new int[LOG][N + 1];
        for (int i = 1; i <= N; i++) up[0][i] = p[i];

        for (int j = 1; j < LOG; j++) {
            for (int i = 1; i <= N; i++) {
                up[j][i] = up[j - 1][up[j - 1][i]];
            }
        }

        int Q = sc.nextInt();
        TreeMap<Integer, Integer> map = new TreeMap<>();
        StringBuilder sb = new StringBuilder();

        for (int qi = 0; qi < Q; qi++) {
            int type = sc.nextInt();

            if (type == 1) {
                int v = sc.nextInt();
                int k = sc.nextInt();

                int c = cover(v, map, tin, tout);
                int ans;

                if (c != 0 && c != v) {
                    if (k == 1) ans = c;
                    else ans = getAncestor(c, k - 1, up, LOG);
                } else {
                    ans = getAncestor(v, k, up, LOG);
                }

                sb.append(ans).append('\n');
            } else {
                int v = sc.nextInt();
                add(v, map, tin, tout);
            }
        }

        System.out.print(sb.toString());
    }

    static int cover(int v, TreeMap<Integer, Integer> map, int[] tin, int[] tout) {
        Integer key = map.floorKey(tin[v]);
        if (key == null) return 0;

        int node = map.get(key);
        if (tin[node] <= tin[v] && tin[v] <= tout[node]) return node;
        return 0;
    }

    static void add(int v, TreeMap<Integer, Integer> map, int[] tin, int[] tout) {
        int c = cover(v, map, tin, tout);
        if (c != 0) return;

        Integer key = map.ceilingKey(tin[v]);
        while (key != null && key <= tout[v]) {
            map.remove(key);
            key = map.ceilingKey(tin[v]);
        }

        map.put(tin[v], v);
    }

    static int getAncestor(int x, int k, int[][] up, int LOG) {
        for (int j = 0; j < LOG; j++) {
            if ((k & (1 << j)) != 0) {
                x = up[j][x];
            }
        }
        return x;
    }
}
